INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64814269', 64814269, 'analyze_legacy', 'Kota Cilegon', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'DED KOLAM RETENSI GPM', 'Jasa Konsultansi', 'Seleksi', 'Banten, Cilegon (Kota)', 143812500, 'February 2026', 'APBD', 1, 1, '1 KEGIATAN', 'Ruang lingkup Pekerjaan DED Kolam Retensi GPM Kota Cilegon mencakup aspek teknis dan administratif sebagai berikut : Evaluasi Kelengkapan Dokumen Perencanaan  Menelaah dokumen teknis seperti : 1. Gambar teknis/kerja (layout, tampak,potongan,detail konstruksi) 2. Rencana anggaran biaya (RAB) 3. Rencana Kerja dan syarat-syarat (RKS)  Memastikan dokumen sesuai standar nasional (SNI) dan peraturan perundangan terkait. Analisis Teknis Desain Tandon 1. Review perhitungan struktur (tandon bawah tanah,tandon atas,kolom,balok,pondasi) 2. Evaluasi kapasitas tandon terhadap debit kebutuhan dan ketersediaan air 3. Kajian stabilitas struktur terhadap gempa dan kondisi tanah eksisting 4. Analisis material (beton,baja,pelapis anti korosi, dan sistem drainase) Sistem Pipa dan Peralatan Meknanikal 1. Review sistem pemipaan masuk dan keluar 2. Evaluasi spesifikasi rumah pompa,pompa,valve,sistem kontrol, dan peralatan pendukung 3. Simulasi hidrolik jika diperlukan untuk sistem distribusi air dari tandon Aspek Hidrologi dan Topografi 1. Verifikasi data curah hujan dan ketersediaan air permukaan atau tanah 2. Peninjauan kontur dan elevasi tanah untuk memastikan kelancaran aliran gravitasi 3. Penyesuaian desain terhadap kondisi eksisting lapangan Review Biaya dan Waktu Pelaksanaan 1. Validasi estimasi biaya dalam RAB terhadap volume pekerjaan dan harga satuan 2. Evaluasi efisiensi anggaran dan kesesuaian dengan standar pemerintah daerah 3. Analisis kelayakan jadwal pelaksanaan dan metode konstruksi Analisis Risiko Teknis 1. Identifikasi potensi risiko konstruksi,kegagalan desain dan faktor eksternal 2. Pemberian rekomendasi mitigasi risiko dari sisi desain dan pelaksanaan 3. Membuat sistem manajemen keselamatan kerja (SMKK) Rekomendasi perbaikan 1. Menyusun daftar ketidaksesuaian,kelemahan,atau potensi penyempurnaan 2. Memberikan catatan teknis dan revisi yang perlu dilakukan sebelum pelaksanaan b. Data dan Fasilitas Penunjang 1. Penyediaan oleh Pengguna Jasa Data dan fasilitas pengguna jasa yang dapat digunakan dan harus dipelihara oleh penyedia jasa (Konsultan) antara lain laporan dan data (bila ada). 2. Penyedia oleh Penyedia Jasa Dalam melaksanakan kegiatan jasa konsultansi teknik, penyedia jasa harus menyediakan semua fasilitas yang diperlukan sebagai berikut : - Kantor/studio lengkap dengan peralatan yang diperlukan untuk pelaksanaan pekerjaan seperti : Komputer, printer, scanner, peralatan gambar, peralatan tulis dan barang habis pakai - Peralatan / instrument pengukuran yang memenuhi standar presisi yang diperlukan dan telah direkomendasikan oleh Direksi /supervise Pekerjaan - Biaya pengadaan tenaga harian dan pembantu yang diperlukan oleh penyedia jasa dalam pelaksanaan pekerjaan', 'jasa konsultansi perencanaan pengairan-Kluster 13 Spesifikasi Harga Biaya Fisik 3.000.000.000 sampai 3.250.000.000', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 591054);
