INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63100166', 63100166, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Pengembangan Modul Layanan Bidang Pengawasan Prasarana', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1500000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 paket', 'Maksud dari kegiatan ini adalah untuk mengembangkan modul layanan digital yang mendukung pengawasan prasarana perkeretaapian secara terintegrasi, akurat, dan realtime, dengan memanfaatkan data dari berbagai sumber serta teknologi terkini seperti sensor dan digital maintenance. Modul ini bertujuan untuk menyediakan data yang dapat digunakan oleh command center di tingkat pusat maupun Balai Teknik Perkeretaapian dalam rangka meningkatkan efektivitas dan efisiensi pengawasan', 'Pengembangan Modul Layanan Bidang Prasarana Perkeretaapian meliputi: Perubahan arsitektur sistem/modul layanan dengan menggunakan teknologi microservices atau arsitektur berorientasi layanan termasuk penyesuaian teknologi standar dengan Portal Layanan dan Data Direktorat Jenderal Perkeretaapian; Optimalisasi penerapan integrasi Single Sign On (SSO), Sistem Penghubung Layanan Transportasi (SPLT) HUBNET Kementerian Perhubungan dan penyediaan API untuk seluruh data yang diproduksi serta dukungan persetujuan terpusat dan datawarehouse perkeretaapian; Melakukan penyesuaian tampilan User Interface (UI) dan User Experience (UX) agar selaras dengan desain dan standar Portal Layanan Direktorat Jenderal Perkeretaapian; Penyeragaman teknologi database sesuai dengan standar Portal Layanan Direktorat Jenderal Perkeretaapian, serta melakukan peningkatan performa database melalui penyederhanaan relasi dan optimasi struktur basis data prasarana perkeretaapian; Penambahan/peningkatan fitur layanan diantaranya : Modul memuat Satu Peta (Spasial) yang mencakup semua data prasarana (Jalur, Jembatan, Terowongan dan Fasilitas Operasi KA) dan dapat melakukan perubahan nama stasiun dan dengan GIS dari Pusdatin; Membuat Form Monitoring dan Evaluasi Pembangunan Prasarana; Membuat fitur pelaporan perawatan dan pemeriksaan prasarana baik oleh Balai maupun Operator (IMO dan Sertifikasi uji berkala); Penyusunan petunjuk teknis untuk melakukan dan menentukan prasarana yang membutuhkan preventif dan corrective maintenance apabila ditemukan error atau terjadi gangguan sistem pada modul layanan serta menyediakan layanan Minor CR (Change Request) untuk melakukan perubahan atau penyesuaian modul layanan yang tidak merubah mekanisme atau prosedur alur kerja modul layanan; Mengidentifikasi kebutuhan informasi dan proses pengawasan prasarana perkeretaapian; Melakukan penyesuaian fitur pada modul layanan pengawasan prasarana perkeretaapian sesuai hasil analisis proses bisnis eksisting dan aplikasi yang telah dibangun sebelumnya seperti master data jembatan, master data jalan rel, kelaikan fasilitas operasi serta Manajemen Material dan Pergudangan Prasarana; Melakukan integrasi dengan aplikasi Sertifikasi Prasarana Perkeretaapian untuk mempercepat proses verifikasi, validasi, dan persetujuan sertifikasi secara terpusat; Peningkatan keamanan dan kinerja Modul Layanan Pengawasan Prasarana Perkeretaapian termasuk melakukan uji keamanan/pentest dan update modul layanan. Workshop/pelatihan untuk penggunaan dan pengolahan Modul Layanan Bidang Pengawasan Prasarana Perkeretaapian.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 592006);
