INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63100585', 63100585, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Pengembangan Modul Layanan Bidang Pengawasan Keselamatan', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1000000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 paket', 'Tersedianya kajian untuk memudahkan kegiatan dan arsip pelaksanaan Audit, Inspeksi serta Penilaian Sistem Keselamatan dan tersedianya Aplikasi Pengelola Hasil Audit, Inspeksi serta Penilaian Sistem Keselamatan Perkeretaapian', 'Ruang lingkup pekerjaan Pembangunan Modul Layanan Pengawasan Keselamatan Perkeretaapian adalah sebagai berikut: Menggunakan teknologi microservices atau arsitektur berorientasi layanan termasuk penyesuaian teknologi standar dengan Portal Layanan dan Data Direktorat Jenderal Perkeretaapian; Optimalisasi penerapan integrasi Single Sign On (SSO) untuk user internal maupun eksternal Kementerian Perhubungan, Sistem Penghubung Layanan Transportasi (SPLT) HUBNET Kementerian Perhubungan dan penyediaan API untuk seluruh data yang diproduksi serta dukungan persetujuan terpusat dan datawarehouse perkeretaapian; Penyesuaian tampilan User Interface (UI) dan User Experience (UX) agar selaras dengan desain dan standar Portal Layanan Direktorat Jenderal Perkeretaapian; Penyeragaman teknologi database sesuai dengan standar Portal Layanan Direktorat Jenderal Perkeretaapian, serta melakukan peningkatan performa database melalui penyederhanaan relasi dan optimasi struktur basis data; Penambahan/peningkatan fitur layanan diantaranya : Melakukan redesign pada modul layanan tanggap darurat / Sistem Informasi Kecelakaan Kereta Api (SIMKA) mengacu pada StrategiHub dan melakukan redesign pada database perlintasan sebidang, peta database daerah rawan menggunakan arsitektur microservices yang terintegrasi pada satu peta perkeretaapian serta pengembangan fitur input, pengolahan dan notifikasi terkait penambahan atau perubahan data perlintasan sebidang; Pembangunan Modul Audit Keselamatan, Modul Penilaian Keselamatan, dan Modul Pengawasan Keselamatan yang mendukung persetujuan terpusat; Pengembangan fitur data laporan kecelakaan sesuai petunjuk teknis; Penerapan fitur Tanda Tangan Elektronik (TTE) yang sudah terintegrasi dengan portal TTE Kementerian Perhubungan dan BSrE untuk memenuhi kebutuhan layanan pengawasan keselamatan perkeretaapian berupa berita acara audit keselamatan; Pengembangan fitur pelaporan, monitoring, dashboard dan GIS (Geospatial Information System) untuk mempermudah pimpinan dalam monitoring hal-hal strategis dengan data, informasi dan laporan secara realtime/update; Penyediaan bukti pengujian fungsional maupun fungsional dari penyedia sistem termasuk unit testing, user acceptance testing, system testing, integration testing, kompabilitas testing, error and exception testing dan performance testing; Peningkatan keamanan dan kinerja Modul Layanan Pengawasan Keselamatan Perkeretaapian termasuk melakukan uji keamanan/pentest dan update modul layanan; Workshop/pelatihan untuk penggunaan dan pengolahan Modul Layanan Sertifikasi Perkeretaapian; Pemeliharaan dilakukan selama 1 tahun setelah serah terima pekerjaan, oleh penerima pekerjaan sesuai dengan RAB dalam studi ini.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 594041);
