INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62490506', 62490506, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'BALAI PELATIHAN DAN PENGEMBANGAN TEKNOLOGI INFORMASI DAN KOMUNIKASI', 'Pengadaan Satuan Pengamanan (Security) di Lingkungan BPPTIK Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bekasi (Kab.)', 1677000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Jasa Pengamanan (Security) di Lingkungan BPPTIK Tahun 2026 dilaksanakan untuk mendukung terciptanya kondisi keamanan, ketertiban, dan kenyamanan di lingkungan BPPTIK, meliputi area gedung, asrama, serta fasilitas penunjang lainnya. Kegiatan ini bertujuan untuk menjaga aset negara, menjamin keselamatan pegawai, peserta pelatihan, dan tamu, serta mendukung kelancaran seluruh aktivitas operasional BPPTIK. Pelaksanaan pekerjaan mencakup penyediaan tenaga pengamanan yang profesional dan terorganisir, dilengkapi dengan struktur komando yang jelas, pemenuhan kewajiban jaminan sosial ketenagakerjaan dan kesehatan, pemberian tunjangan-tunjangan yang sah, serta penyediaan perlengkapan dan peralatan pengamanan. Seluruh biaya pengadaan sudah termasuk keuntungan perusahaan dan seluruh pajak yang berlaku.', '1. Lingkup Umum Pekerjaan Pelayanan jasa pengamanan meliputi seluruh area lingkungan BPPTIK, antara lain: - Gedung utama dan gedung penunjang - Asrama - Area perkantoran - Area pelatihan dan fasilitas pendukung - Area parkir - Pintu masuk dan keluar lingkungan BPPTIK - dan gedung / area lainnya di lingkungan BPPTIK Kegiatan pengamanan meliputi penjagaan, pengawasan, patroli rutin dan insidentil, pengendalian akses keluar masuk, serta penanganan awal gangguan keamanan sesuai prosedur yang berlaku. 2. Personel Pelaksana Pelaksanaan jasa pengamanan didukung oleh personel sebagai berikut: - Kepala Satpam / Chief Security - Supervisor Keamanan - Komandan Regu - Anggota Jumlah petugas pengamanan sebanyak 17 (tujuh belas) orang dengan masa kerja selama 11 (sebelas) bulan. 3. Key Performance Indicator (KPI) - Terselenggaranya jasa pengamanan selama 11 (sebelas) bulan sesuai kontrak - Terjaganya keamanan, ketertiban, dan kenyamanan lingkungan BPPTIK - Tidak terjadinya gangguan keamanan yang berdampak signifikan terhadap operasional BPPTIK 4. Komponen Biaya Biaya pengadaan jasa pengamanan sudah termasuk seluruh komponen biaya sebagai berikut: - Gaji Pokok petugas pengamanan (17 orang x 11 bulan) - Jaminan Sosial Ketenagakerjaan dan Kesehatan, meliputi: Jaminan Kematian (JK) Jaminan Kecelakaan Kerja (JKK) Jaminan Hari Tua (JHT) Jaminan Pensiun (JP) Jaminan Pemeliharaan Kesehatan (JPK) Tunjangan Hari Raya (THR) Tunjangan Kepala Satpam / Chief Security Tunjangan Supervisor Tunjangan Komandan Regu Keuntungan perusahaan Seluruh pajak yang berlaku sesuai ketentuan peraturan perundang-undangan 5. Peralatan dan Perlengkapan Peralatan dan perlengkapan kerja yang termasuk dalam biaya pengadaan jasa pengamanan antara lain: - Pakaian Dinas Harian/Lapangan (PDH/PDL) - Pakaian Dinas Safari - Pakaian Dinas Polo Security - Sepatu PDH - Sepatu PDL - Sepatu Boor karet - Handy Talky (HT) dengan jangkauan minimal 1–2 km - Lampu senter - Lampu lalu lintas - Jas hujan - Tongkat T - Mesin absensi 6. Jangka Waktu Pelaksanaan Pekerjaan jasa pengamanan dilaksanakan selama 11 (sebelas) bulan, terhitung sejak bulan Januari sampai dengan November Tahun Anggaran 2026, sesuai dengan ketentuan yang tercantum dalam kontrak. 7. Mekanisme Pembayaran Pembayaran dilakukan secara per termin sesuai dengan ketentuan yang tercantum dalam kontrak dan peraturan perundang-undangan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 594991);
