INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62491083', 62491083, 'analyze_legacy', 'Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN', 'central', 'Perwakilan BKKBN Provinsi Nusa Tenggara Barat', 'Syringe', 'Barang', 'E-Purchasing', 'Nusa Tenggara Barat, Mataram (Kota)', 92631000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 56140, Buah, @ 1650 )', '1. Syringe ( 56140, Buah, @ 1650 );', '- Deskripsi Disposable Syringe adalah alat yang ditujukan untuk tujuan medis yang terdiri dari per barel berongga terkalibrasi dan plunger yang dapat digerakkan. Pada salah satu ujung barel ada konektir jantan (nozzle) untuk pemasangan konektor betina (hub) dari jarum suntik lumen tunggal. Alat ini digunakan untuk menyuntikkan cairan ke dalam, atau menarik cairan dari tubuh dan digunakan untuk sekali pakai. - Spesifikasi 1) Spesifikasi Umum a) Disposable Syringe (Alat Suntik Sekali Pakai) (1) Kapasitas Volume : 3.0 ml (2) Ukuran Jarum : 23G x 1 ¼” (3) Parameter Uji : sesuai dengan produk yang didaftarkan ke Kementerian Kesehatan RI b) Registrasi Memiliki Nomor Ijin Edar (NIE) dari Kementerian Kesehatan RI dan masih berlaku c) Masa Kadaluarsa Minimal 3 (tiga) tahun sejak dilakukan penyerahan barang di gudang Perwakilan BKKBN Provinsi Nusa Tenggara Barat dan atau Tahun Produksi yang disesuaikan dengan tahun pengadaan. 2) Spesifikasi Khusus Pelabelan/Penandaan kemasan Disposable Syringe mengikuti peraturan perundang-undangan yang berlaku dan informasi tambahan yang ditetapkan Kemendukbangga/BKKBN sebagai berikut: a) Individual pack: (1) Setiap alat dikemas dalam plastik steril transparan; (2) Pada setiap individual pack harus tercantum nomor batch, nomor registrasi, tahun produksi dan batas kadaluarsa (tanggal, bulan, tahun) (3) Pada setiap individual pack tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar: (4) Setiap individual pack tercantum tulisan “Kemendukbangga/BKKBN APBN Tahun Anggaran 2026” dengan warna hitam/biru dan “Tidak diperjualbelikan” dengan warna merah. b) Inner Box (Box Kecil) (1) Pada setiap inner box tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar; (2) Pada inner box tertulis nomor batch, nomor registrasi, tahun produksi dan tahun kadaluarsa (tanggal, bulan dan tahun) dengan warna biru/hitam; (3) Setiap inner box tercantum tulisan “Kemendukbangga/BKKBN APBN Tahun Anggaran 2026” dengan warna biru/hitam dan tulisan “Tidak diperjualbelikan” dengan warna merah; (4) Pada setiap inner box dilengkapi dengan petunjuk pemakaian dalam Bahasa Indonesia, 1 copy untuk setiap inner box. c) Outer Box (1) Pada setiap Outer box tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar; (2) Pada Outer box tertulis nomor batch, nomor registrasi, tahun produksi dan tahun kadaluarsa (tanggal, bulan dan tahun) dengan warna biru/hitam; (3) Setiap Outer box tercantum tulisan “Kemendukbangga/BKKBN APBN Tahun Anggaran 2026” dengan warna biru/hitam dan tulisan “Tidak diperjualbelikan” dengan warna merah; (4) Ketebalan Karton Outer Box menyesuaikan dengan jenis dan berat produk agar dapat terjamin keamanan, mutu, dan manfaat produk.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 595699);
