INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63101551', 63101551, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Pengembangan Modul Layanan Bidang Pengawasan Sarana', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1000000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 paket', 'Maksud dari kegiatan adalah meningkatkan dan memastikan kehandalan Modul Layanan Bidang Pengawasan Sarana Perkeretaapian', 'Pengembangan Modul Layanan Bidang Pengawasan Sarana Perkeretaapian meliputi: Perubahan arsitektur sistem/modul layanan dengan menggunakan teknologi microservices atau arsitektur berorientasi layanan termasuk penyesuaian teknologi standar dengan Portal Layanan dan Data Direktorat Jenderal Perkeretaapian. Optimalisasi penerapan integrasi Single Sign On (SSO), SPLT (Sistem Penghubung Layanan Transportasi) HUBNET Kementerian Perhubungan dan sistem tracking serta data perawatan sarana milik operator pada Modul Layanan Bidang Pengawasan Sarana Perkeretaapian yang terintegrasi dengan Portal Layanan Direktorat Jenderal Perkeretaapian (superapps) mendukung persetujuan terpusat dan data warehouse termasuk integrasi sistem dengan eksternal Direktorat Jenderal Perkeretaapian. Penyesuaian tampilan User Interface (UI) dan User Experience (UX) agar selaras dengan desain dan standar Portal Layanan Direktorat Jenderal Perkeretaapian. Penyeragaman teknologi database sesuai dengan standar Portal Layanan Direktorat Jenderal Perkeretaapian, serta melakukan peningkatan performa database melalui penyederhanaan relasi dan optimasi struktur basis data sarana perkeretaapian. Penambahan/peningkatan fitur layanan diantaranya : Peningkatan fitur layanan diantaranya integrasi layanan penetapan identitas sarana, layanan perawatan sarana milik negara, penambahan fitur layanan pengaduan. Penambahan fitur pengusulan spesifikasi teknis sarana perkeretaapian; Peningkatan fitur perawatan dan pemeliharaan sarana perkeretaapian seperti penjadwalan, check sheet, laporan dan lainnya. Penerapan fitur Tanda Tangan Elektronik (TTE) yang sudah terintegrasi dengan portal TTE Kementerian Perhubungan dan BSrE untuk memenuhi kebutuhan layanan pengawasan sarana. Pengembangan fitur pelaporan, monitoring, dashboard dan GIS (Geospatial Information System) untuk mempermudah pimpinan dalam monitoring hal-hal strategis dengan data, informasi dan laporan secara realtime/update. Peningkatan user dan role management terkait penggunaan Modul Layanan Bidang Pengawasan Sarana Perkeretaapian termasuk integrasi dengan SIK Kementerian Perhubungan. Peningkatan keamanan dan kinerja Modul Layanan Bidang Pengawasan Sarana Perkeretaapian termasuk melakukan uji keamanan/pentest dan update modul layanan. Workshop/pelatihan untuk penggunaan dan pengolahan Modul Layanan Bidang Pengawasan Sarana Perkeretaapian.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 596653);
