INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62491086', 62491086, 'analyze_legacy', 'Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN', 'central', 'Perwakilan BKKBN Provinsi Nusa Tenggara Barat', 'Suntikan Progestin', 'Barang', 'E-Purchasing', 'Nusa Tenggara Barat, Mataram (Kota)', 322900000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 50000, vial, @ 6458 )', '1. Suntikan Progestin ( 50000, vial, @ 6458 );', 'Suntik KB 1 ml Tiap vial mengandung bahan aktif 150mg Medroxyprogesterone Acetate dalam 1 ml injeksi steril; b. Spesifikasi Mutu 1. Memiliki Nomor Izin Edar yang masih berlaku; 2. Memiliki sertifikat CPOB yang masih berlaku; 3. Sertifikat CDOB yang masih berlaku; 4. Memiliki CoA yang memenuhi syarat. c. Sesuai dengan produk yang terdaftar ke Kementerian Kesehatan RI d. Masa Kadaluarsa Paling Sedikit 2,5 (Dua Setengah) tahun sejak diterima di gudang Perwakilan BKKBN Provinsi Nusa Tenggara Barat. - Spesifikasi Khusus: Kemasan Suntik KB mengikuti persyaratan Nomor Ijin Edar dari BPOM dan informasi tambahan dari Kemendukbangga/BKKBN sebagai berikut: a. Individual Pack 1. Tercantum nomor batch/lot, nomor registrasi, waktu produksi (Bulan, Tahun) dan masa kadaluarsa (tanggal, bulan dan tahun) 2. Tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar; 3. Pada setiap individual pack tercantum tulisan “Kemendukbangga/BKKBN APBN Tahun Anggaran 2026” Dengan warna hitam/biru dan “Tidak diperjualbelikan” dengan warna merah. 4. Ketentuan sebagaimana disebutkan pada angka (3) dikecualikan pada: i. Produk impor yang sudah beredar di Indonesia dan pengemasanannya dilakukan di negara asal; ii. Tidak tersedia ruang yang memadai; iii. Perubahan ketentuan atau logo Kemendukbangga/BKKBN dan nomenklatur lembaga. 5. Jumlah Individual Pack yang dimasukkan kedalam inner box disesuaikan dengan kemasan yang tercantum dalam NIE. b. Inner Box 1. Dilengkapi dengan 1 copy petunjuk pemakaian dalam Bahasa Indonesia untuk setiap unit; 2. Tercantum nama produk sesuai dengan nama produk di dokumen izin edar; 3. Terdapat tulisan nomor batch/lot, nomor registrasi, waktu produksi dan masa kadaluarsa (Tanggal, Bulan dan Tahun); 4. Pada inner box tercantum tulisan “Kemendukbangga/BKKBN APBN Tahun Anggaran 2026 dan “Tidak diperjualbelikan” dengan warna merah.” 5. Jumlah inner box dimasukkan ke dalam outer box disesuaikan dengan kemasan yang tercantum dalam NIE; 6. Ketentuan sebagaimana disebutkan pada angka (4) dikecualikan pada: i. Produk impor yang sudah beredar di Indonesia dan pengemasanannya dilakukan di negara asal; ii. Tidak tersedia ruang yang memadai; iii. Perubahan ketentuan atau logo Kemendukbangga/BKKBN dan nomenklatur lembaga. c. Outer Box (Box Besar) 1. Tercantum nama produk sesuai dengan nama produk di dokumen izin edar; 2. Terdapat tulisan nomor batch/lot, nomor registrasi, waktu produksi (Bulan, Tahun) dan masa kadaluarsa (Tanggal, Bulan dan Tahun) tertulisa pada dua sisi; 3. Pada outer box tercantum tulisan “Kemendukbangga/BKKBN APBN Tahun Anggaran 2026 dan “Tidak diperjualbelikan” dengan warna merah.” 4. Ketentuan sebagaimana disebutkan pada angka (3) dikecualikan pada: i. Produk impor yang sudah beredar di Indonesia dan pengemasanannya dilakukan di negara asal; ii. Tidak tersedia ruang yang memadai.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 597687);
