INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62490434', 62490434, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'BALAI PELATIHAN DAN PENGEMBANGAN TEKNOLOGI INFORMASI DAN KOMUNIKASI', 'Pengadaan Petugas Kebersihan (Cleaning Service) di Lingkungan BPPTIK Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bekasi (Kab.)', 1985500000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Jasa Kebersihan dilaksanakan untuk mendukung terjaganya kebersihan, kerapihan, dan keindahan lingkungan BPPTIK secara berkesinambungan, meliputi area gedung, asrama, serta fasilitas penunjang lainnya. Kegiatan ini bertujuan untuk menciptakan lingkungan kerja dan pelatihan yang bersih, rapi, sehat, dan nyaman bagi seluruh pengguna layanan BPPTIK. Pelaksanaan pekerjaan mencakup penyediaan tenaga kebersihan yang profesional dan terorganisir, dilengkapi dengan koordinator/supervisor, penyediaan seragam dan perlengkapan kerja, pemenuhan kewajiban jaminan ketenagakerjaan dan kesehatan, pemberian tunjangan hari raya, serta pelaksanaan kegiatan kebersihan sesuai standar selama jangka waktu kontrak 12 (dua belas) bulan. Seluruh biaya pengadaan sudah termasuk keuntungan perusahaan serta seluruh pajak yang berlaku.', '1. Lingkup Umum Pekerjaan Pelayanan jasa kebersihan meliputi seluruh area lingkungan BPPTIK, antara lain: - Gedung utama dan gedung penunjang - Asrama - Ruang perkantoran - Ruang kelas dan ruang pelatihan - Toilet dan kamar mandi - Koridor, tangga, dan area sirkulasi - Area luar gedung serta fasilitas penunjang lainnya Kegiatan kebersihan meliputi pembersihan rutin, berkala, dan insidentil sesuai kebutuhan operasional BPPTIK. 2. Personel Pelaksana a. Koordinator / Team Leader Kebersihan Koordinator/Team Leader Kebersihan adalah personel yang bertugas: - Mengoordinasikan, mengawasi, dan mengendalikan pelaksanaan pekerjaan petugas kebersihan - Memastikan standar kebersihan dan kerapihan terpenuhi sesuai kontrak - Menjadi penghubung antara penyedia jasa dan pihak BPPTIK b. Petugas Kebersihan Petugas Kebersihan adalah personel yang bertugas: - Menjaga, memelihara, dan merawat kebersihan serta keindahan area gedung dan lingkungan BPPTIK - Melaksanakan kegiatan kebersihan harian, berkala, dan insidentil sesuai kebutuhan - Jumlah petugas kebersihan sebanyak 19 (sembilan belas) orang dengan masa kerja selama 12 (dua belas) bulan. 3. Key Performance Indicator (KPI) - Terselenggaranya jasa kebersihan selama 12 (dua belas) bulan sesuai kontrak - Tercapainya standar kebersihan dan kerapihan lingkungan BPPTIK - Terwujudnya lingkungan BPPTIK yang bersih, rapi, sehat, dan nyaman 4. Komponen Biaya Harga paket pengadaan sudah termasuk seluruh komponen biaya sebagai berikut: - Gaji pokok petugas kebersihan (19 orang x 12 bulan) - Jaminan Sosial Ketenagakerjaan dan Kesehatan, meliputi: Jaminan Kematian (JK) Jaminan Kecelakaan Kerja (JKK) Jaminan Hari Tua (JHT) Jaminan Pensiun (JP) Jaminan Pemeliharaan Kesehatan Tunjangan Hari Raya (THR) Tunjangan Supervisor Keuntungan perusahaan Seluruh pajak yang berlaku sesuai ketentuan peraturan perundang-undangan 5. Peralatan dan Perlengkapan Peralatan dan perlengkapan kerja yang termasuk dalam biaya pengadaan antara lain: - Seragam Custom Cleaning Service (19 orang x 2 stel) - Sepatu boot karet - Sepatu kerja - Mesin absensi 6. Jangka Waktu Pelaksanaan Jangka waktu pelaksanaan pekerjaan adalah 12 (dua belas) bulan sejak tanggal kontrak berlaku. 7. Mekanisme Pembayaran Pembayaran dilakukan secara per termin sesuai dengan ketentuan yang tercantum dalam kontrak dan peraturan perundang-undangan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 597758);
