INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62490296', 62490296, 'analyze_legacy', 'Kab. Klaten', 'kabkota', 'BAGIAN UMUM', 'belanja ongkos jahit seragam HUT', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Tengah, Klaten (Kab.)', 25500000, 'May 2026', 'APBD', 1, 1, '170 org', 'belanja ongkos jahit seragam', 'belanja ongkos jahit seragam', 25500000, 'high', 'Pengadaan ongkos jahit seragam untuk peringatan HUT berindikasi tidak prioritas terhadap fungsi pelayanan publik dan cenderung bersifat seremonial. Dengan cakupan 170 orang, seluruh nilai pengadaan patut dicermati sebagai potensi pemborosan bila tidak didukung kebutuhan kedinasan yang jelas.', NULL, NULL, 3, 1, 1, 1, 1, 598262);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63103290', 63103290, 'analyze_legacy', 'Kementerian Energi Dan Sumber Daya Mineral', 'central', 'SEKRETARIAT JENDERAL KEMENTERIAN ENERGI DAN SUMBER DAYA MINERAL', 'Peningkatan Kapasitas Pengelolaan Media Sosial Pimpinan ESDM', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 50000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Peningkatan Kapasitas Pengelolaan Media Sosial Pimpinan merupakan kegiatan strategis untuk mendukung efektivitas komunikasi pimpinan dalam menyampaikan kebijakan, arahan, dan sikap institusi kepada publik melalui media sosial. Kegiatan ini bertujuan membekali tim pendukung pimpinan dengan pemahaman dan keterampilan dalam mengelola akun media sosial pimpinan secara profesional, kredibel, dan beretika, serta selaras dengan kebijakan komunikasi pemerintah. Melalui penguatan strategi personal branding kelembagaan, pengelolaan konten yang tepat sasaran, serta manajemen isu dan krisis komunikasi, diharapkan media sosial pimpinan dapat menjadi sarana komunikasi yang informatif, persuasif, dan responsif terhadap dinamika publik.', 'Pekerjaan ini meliputi perencanaan, pelaksanaan, dan evaluasi kegiatan peningkatan kapasitas sumber daya manusia dalam pengelolaan media sosial Kementerian ESDM agar lebih profesional, efektif, dan selaras dengan kebijakan komunikasi publik pemerintah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 598263);
