INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63102078', 63102078, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Komunikasi dan Informatika', 'Perawatan Rutin Kelistrikan Pusat Komputasi', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kota)', 197000000, 'January 2026', 'APBD', 0, 1, '1 paket', 'Pada tahapan ini pelaksanaan perawatan dilakukan meliputi : Penyusunan Diagram satu garis ( Single Line Diagram ) Pemetaan Rute Kabel dari gardu hingga rak server Pelebelan seluruh komponen Membuat laporan konferhensif audit sistem kelistrikan Melaksanakan inventarisasi komponen Membuat Dokumentasi Diagram dan Rute Kabel Pengukuran Parameter kelistrikan (tegangan, arus, daya, faktor daya, harmonisa, grounding) Melaporkan Hasil Pekerjaan melalui Kartu Kendali', 'Audit kapasitas daya dan beban (gardu, panel, UPS, genset). Pengukuran parameter kelistrikan (tegangan, arus, daya, faktor daya, harmonisa, grounding). Identifikasi kondisi komponen kelistrikan existing Penyusunan diagram satu garis (single line diagram). Pemetaan rute kabel dari gardu hingga rak server data center. Identifikasi dan pelabelan seluruh komponen. Analisis perbandingan kapasitas daya terpasang vs beban aktual. Evaluasi redundansi sistem kelistrikan. Analisis efisiensi, keandalan, dan ketersediaan sistem. Penyusunan rekomendasi teknis untuk peningkatan kapasitas/perbaikan. Laporan komprehensif hasil audit sistem kelistrikan. Dokumentasi diagram, peta rute kabel, dan inventarisasi. Hasil analisis dan rekomendasi perbaikan. Penyerahan dokumen dalam format hardcopy dan softcopy Support Trouble 1x24 Jam (Support Emergency)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 599772);
